import json, os
base='audit/batch4_rawls'
change=json.load(open(os.path.join(base,'round8_transform_material_change.json')))
check=json.load(open(os.path.join(base,'round8_final_reopen_validation.json')))
pre={o['name']:o for o in change['before']['targets']}
post={o['name']:o for o in check['fixed_objects']}
selected=list(pre)
rows=[]
for n in selected:
 b,a=pre[n],post[n]
 rows.append({'name':n,'type':b['type'],'parent':b['parent'],'before_world_bounds':b['world_bounds'],'after_world_bounds':a['world_bounds'],'before_location':b['location'],'after_location':a['location'],'before_matrix_parent_inverse':b['matrix_parent_inverse'],'after_matrix_parent_inverse':a['parent_inverse'],'before_matrix_world':b['matrix_world'],'after_matrix_world':a['world_matrix'],'mesh_sha256_before':b['mesh_sha256'],'mesh_sha256_after':a['mesh_sha256']})
shell_before=change['before']['structural_shell'];shell_after=check['shell']
root_before=change['before']['root'];root_after=check['root']
assert shell_before['matrix_world']==shell_after['world_matrix']
assert shell_before['mesh_sha256']==shell_after['mesh_sha256']
assert root_before['matrix_world']==root_after['world_matrix']
assert not check['materialless_meshes'] and not check['external_file_images'] and not check['linked_libraries'] and not check['mesh_local_bounds_outliers']
final={'asset':check['asset'],'sha256':check['sha256'],'fresh_reopen':True,'scene':check['scene'],'collection':'Asset_rawls_hall','object_count':check['objects'],'mesh_count':check['meshes'],'materialless_meshes':check['materialless_meshes'],'external_file_images':check['external_file_images'],'linked_libraries':check['linked_libraries'],'campus_local_mesh_bounds_outliers':check['mesh_local_bounds_outliers'],'repaired_objects':rows,'root_before':root_before,'root_after':root_after,'structural_shell_before':shell_before,'structural_shell_after':shell_after,'shell_and_root_exactly_unchanged':True,'renders':{'north':'north_exterior_round8.png','south':'south_exterior_round8.png','south_aperture_detail':'south_aperture_detail_round8.png','sidewalk':'sidewalk_southwest_round8.png'},'material_adjustments':change['after']['glass']|{'mortar':change['after']['mortar']},'uncertainties':['Campus XY is a local approximate geographic conversion, not surveyed control; prior comparison retains about 1–2 m GIS/Plan1086 edge-registration uncertainty.','The 2024 Purdue first-floor plan supports first-floor partitions only; upper floors and atrium circulation remain schematic/estimated.','Exterior render views verify the modeled appearance only, not current facade colors or verified GIS/building elevations.','Only two frames of eight existing south-facing panes have been repaired from the stale offset; other south façade recesses remain opaque-looking in the full elevation, and no claim is made that every remaining elevation has validated apertures.']}
json.dump(final,open(os.path.join(base,'round8_final_evidence.json'),'w'),indent=2)
lines=['# Rawls Hall round 8 repair and reopen evidence','',f'- Asset: `modular/buildings/rawls_hall.blend`',f'- Reopened saved asset SHA-256: `{check["sha256"]}`',f'- Reopened scene/export collection: `{check["scene"]}` / `Asset_rawls_hall` ({check["objects"]} objects; {check["meshes"]} meshes).', '- No materialless meshes, external image files, linked libraries, or campus-local mesh-bound outliers were found. All image/material data remains self-contained.', '- The root remains identity. The structural-shell matrix and mesh-geometry SHA-256 match the pre-edit snapshot exactly; the shell was not edited.', '', '## Transform repair', '', 'The following six cameras and two meshes had `matrix_parent_inverse` translation `(-323.6582336426, +409.6224365234, 0)` before repair. It was reset to identity while preserving object locations and mesh vertices. Before/after full world matrices and three-axis world bounds are in `round8_final_evidence.json`.', '', '| Object | Before world bounds X / Y / Z (m) | Reopened after bounds X / Y / Z (m) |', '|---|---|---|']
for r in rows:
 def fmt(bounds):return ' / '.join(f'{v[0]:.3f}…{v[1]:.3f}' for v in bounds)
 lines.append(f'| `{r["name"]}` | {fmt(r["before_world_bounds"])} | {fmt(r["after_world_bounds"])} |')
lines+=['','The sidewalk apron returned from the false bounds `X -355…-273, Y 383…432` to its local apron extent `X -31.346…50.321, Y -26.226…22.610, Z 0.012`. The south bronze mullions returned from `X -334.390…-328.724, Y 385.255…385.382` to `X -10.732…-5.066, Y -24.367…-24.241, Z 1.100…19.267`. Six saved cameras also returned from false world positions hundreds of metres away to their authored Rawls-local positions; exact full matrices are listed in the JSON record.','', '## Evidence renders','', '- North exterior: `north_exterior_round8.png`', '- South full elevation: `south_exterior_round8.png`', '- South aperture detail: `south_aperture_detail_round8.png`', '- Sidewalk/apron context: `sidewalk_southwest_round8.png`','', 'The R8 material adjustment made the existing shared architectural glass somewhat more transparent and reduced the brightness of both brick-texture mortar values by 18%; no mesh geometry changed. The south detail confirms glazing/frames at the existing eight south panes. The wider south elevation still has opaque-looking recesses beyond that limited pane group; correcting every south recess would require additional source-supported aperture geometry and was not included in this repair.','', '## Remaining uncertainty','', '- Approximate GIS/Plan1086 edge registration remains uncertain by about 1–2 m; this local conversion is not a survey-grade CRS.', '- The 2024 Purdue plan supports the documented first-floor partitions. Upper-floor layouts and atrium circulation remain schematic/estimated.', '- Rendered material appearance is an authored representation; no current source verifies exact facade colors or height.', '- The round 8 repairs do not claim all remaining elevations are fully apertured or photographically verified.','']
open(os.path.join(base,'round8_final_evidence.md'),'w').write('\n'.join(lines))
print('wrote',os.path.join(base,'round8_final_evidence.json'))
print('wrote',os.path.join(base,'round8_final_evidence.md'))
print('rows',len(rows),'hash',check['sha256'])
